package coinmetrics;
import java.math.*;import java.nio.file.*;import java.util.*;
public final class CoreTests{
 static int passed=0;
 static void check(boolean c,String message){if(!c)throw new AssertionError(message);passed++;}
 public static void main(String[] args)throws Exception{
 check(Core.demoAssets().size()==10,"demo asset count");check(Core.demoAssets().get(0).symbol().equals("BTC"),"assets order");check(Core.demoSeries("ETH",30).size()==30,"history length");check(Core.demoSeries("ETH",30).get(0).value()>0,"positive history");
 check(Core.amount("0.00000001").compareTo(new BigDecimal("0.00000001"))==0,"fractional quantity");check(Core.money("0.00").signum()==0,"zero cost");check(Core.value(new BigDecimal("1.25"),100).compareTo(new BigDecimal("125.00"))==0,"valuation");check(Math.abs(Core.percent(120,100)-20)<0.0001,"return pct");
 for(String bad:List.of("0","-1","abc","0.000000001","1000000001")){boolean failed=false;try{Core.amount(bad);}catch(IllegalArgumentException e){failed=true;}check(failed,"reject invalid quantity "+bad);}
 for(String bad:List.of("-1","abc","1.001")){boolean failed=false;try{Core.money(bad);}catch(IllegalArgumentException e){failed=true;}check(failed,"reject invalid basis "+bad);}
 Core.Portfolio p=new Core.Portfolio();p.put("BTC",new BigDecimal("0.5"),new BigDecimal("15000"));p.put("ETH",new BigDecimal("2"),new BigDecimal("1000"));check(p.all().size()==2,"holdings added");Map<String,Core.Asset> prices=new HashMap<>();for(Core.Asset a:Core.demoAssets())prices.put(a.symbol(),a);check(p.total(prices).compareTo(new BigDecimal("41150.00"))==0,"total value");check(p.invested().compareTo(new BigDecimal("16000"))==0,"total invested");Path f=Files.createTempFile("coinmetrics", ".csv");p.save(f);Core.Portfolio q=new Core.Portfolio();q.load(f);check(q.all().size()==2,"persist holdings");check(q.invested().compareTo(p.invested())==0,"persist cost basis");q.remove("ETH");check(q.all().size()==1,"remove holding");Files.deleteIfExists(f);
 Core.Portfolio trading=new Core.Portfolio();trading.buy("BTC",new BigDecimal("2"),new BigDecimal("200"));check(trading.all().size()==1,"purchase creates position");trading.buy("BTC",new BigDecimal("1"),new BigDecimal("130"));check(trading.invested().compareTo(new BigDecimal("330"))==0,"purchase sums cost basis");check(trading.all().get(0).quantity().compareTo(new BigDecimal("3"))==0,"purchase sums quantity");check(trading.sell("BTC",new BigDecimal("1"),new BigDecimal("150")).compareTo(new BigDecimal("40.00"))==0,"average basis realized gain");check(trading.invested().compareTo(new BigDecimal("220.00"))==0,"remaining basis after sale");check(trading.all().get(0).quantity().compareTo(new BigDecimal("2"))==0,"remaining quantity after sale");boolean rejected=false;try{trading.sell("BTC",new BigDecimal("3"),new BigDecimal("150"));}catch(IllegalArgumentException e){rejected=true;}check(rejected,"oversell rejected");check(trading.sell("BTC",new BigDecimal("2"),new BigDecimal("300")).compareTo(new BigDecimal("80.00"))==0,"closing position realized gain");check(trading.all().isEmpty(),"closing position removes holding");
 Object doc=Core.Json.read("{\"quotes\":{\"USD\":{\"price\":23.45}},\"items\":[1,true,null,\"x\\nY\"]}");check(doc instanceof Map,"JSON map");Object quote=((Map<?,?>)((Map<?,?>)doc).get("quotes")).get("USD");check(Math.abs(((Number)((Map<?,?>)quote).get("price")).doubleValue()-23.45)<.00001,"nested JSON");check(((List<?>)((Map<?,?>)doc).get("items")).size()==4,"JSON array");
 for(int i=0;i<10;i++){check(Core.demoSeries(Core.SYMBOLS[i],7).size()==7,"asset series "+i);check(Core.demoAssets().get(i).price()>0,"positive price "+i);}
 System.out.println("PASS: "+passed+" CoinMetrics core assertions");
 }
}
